import{_ as i,o as t,c as a,a3 as s}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Living in Qatar","titleTemplate":"A sourced guide for residents","description":"","frontmatter":{"layout":"home","title":"Living in Qatar","titleTemplate":"A sourced guide for residents","hero":{"name":"Living in Qatar","text":"A practical guide with a source for every claim","tagline":"Visas, QID, health, housing, work, money and daily life. Each fact links to the official page it comes from, with the month it was last checked. Free, in English and Arabic, and open to corrections.","image":{"src":"/favicon.svg","alt":""},"actions":[{"theme":"brand","text":"Start reading","link":"/guide/"},{"theme":"alt","text":"First 30 days checklist","link":"/checklist"},{"theme":"alt","text":"العربية","link":"/ar/"}]},"features":[{"title":"Just arrived","details":"Entry visas, the residence permit and QID, and the Metrash app.","link":"/guide/residence-permit-and-qid","linkText":"Residence permit and QID"},{"title":"Working or looking for work","details":"Contracts, wages, leave, end of service pay and changing employers.","link":"/guide/work-and-labour-rights","linkText":"Work and labour rights"},{"title":"Bringing your family","details":"Family residence and visit visas, and finding a school for your children.","link":"/guide/family-visas","linkText":"Family visas"},{"title":"Renting a home","details":"Leases, rental disputes, and getting electricity and water connected.","link":"/guide/housing-and-utilities","linkText":"Housing and renting"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function o(r,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h2 id="why-this-guide-exists" tabindex="-1">Why this guide exists <a class="header-anchor" href="#why-this-guide-exists" aria-label="Permalink to &quot;Why this guide exists&quot;">​</a></h2><p>Most advice for new residents lives in forum threads, group chats and blog posts. Some of it is good, a lot of it is out of date, and almost none of it says where the information came from. Official pages exist for nearly everything, but they are spread over many ministries and websites.</p><p>This guide puts the practical steps in one place and links every fact to the official page it comes from, so you can check it yourself before you act.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li><strong>A footnote on every claim.</strong> Each paragraph points to the exact official page, with the month it was last checked.</li><li><strong>Two languages, same sources.</strong> The English and Arabic pages cite the same pages, and a check fails if they drift apart.</li><li><strong>Checked by a script.</strong> A link checker visits every source and flags pages that disappear, move or change. Sites that turn away scripts are listed so someone can check them in a browser.</li><li><strong>Open to corrections.</strong> Every page has an edit link. If something is out of date, send a correction with the official page that shows the right information.</li></ul><p>Read <a href="./sourcing">how we source things</a> or see the <a href="./help-wanted">topics we still need help with</a>.</p><div class="warning custom-block"><p class="custom-block-title">Not legal advice</p><p>This is a community guide, not a government service. Rules, fees and procedures change. Always confirm on the official page linked in the sources before you act.</p></div>',7)])])}const f=i(n,[["render",o]]);export{p as __pageData,f as default};
